```rust
#[tool(description = "Explore a topic in the codebase. Returns a ranked list of matching symbols with literal sutra_read fetch instructions and a strategy recommendation. One call replaces iterative map/outline/grep exploration.")]
pub async fn sutra_explore(
    &self,
    Parameters(args): Parameters<ExploreArgs>,
) -> Result<String, ErrorData> {
    let ctx = self.tool_context(&args.workspace)?;
    let budget = args.budget.unwrap_or(10);
    let result = tools::explore::handle(ctx.db(), &args.query, budget)
        .map_err(sutra_to_rmcp)?;
    to_compact_json(ctx.wrap(result))
}
```

### Step 7: Integration tests in `tests/mcp_contract_test.rs`

Two tests: basic query with hits, and zero-hit case. Follow existing pattern — `setup_test_db()`, insert symbols with greppable names, call `explore::handle()` directly, assert on response structure.

```rust
#[test]
fn test_explore_basic() {
    let (_dir, db) = setup_test_db();
    // Insert symbols: "parse_imports" (fn), "resolve_imports" (fn), "handle_exports" (fn)
    // via db.insert_symbol(&InsertSymbolParams { short_name: "parse_imports", ... })
    let result = explore::handle(&db, "import", 10).unwrap();

    let items = result["items"].as_array().expect("items array");
    assert!(items.len() >= 2, "should match parse_imports and resolve_imports");
    for item in items {
        assert!(item["symbol"].is_string());
        assert!(item["file"].is_string());
        assert!(item["kind"].is_string());
        assert!(item["lines"].is_i64());
        assert!(item["estimated_tokens"].is_i64());
        let fetch = item["fetch"].as_str().unwrap();
        assert!(fetch.starts_with("sutra_read(symbol='"), "fetch must be a literal sutra_read call");
    }
    assert!(result["strategy"]["action"].is_string());
    assert!(result["strategy"]["rationale"].is_string());
    assert!(result["summary"]["total_items"].is_i64());
    assert!(result["summary"]["total_estimated_tokens"].is_i64());
}

#[test]
fn test_explore_zero_hits() {
    let (_dir, db) = setup_test_db();
    let result = explore::handle(&db, "nonexistent_xyzzy", 10).unwrap();
    let items = result["items"].as_array().unwrap();
    assert!(items.is_empty());
    assert_eq!(result["strategy"]["action"].as_str().unwrap(), "narrow_query");
}
```

